 * Serializes a request body for a Swagger "try it out" request.
 *
 * Swagger UI hands us the body in whatever shape the fetch spec allows
 * (string, URLSearchParams, FormData, Blob, File, ArrayBuffer, TypedArray, ...).
 * We can only forward text-based bodies through the Bruno proxy, so anything
 * binary or multipart is rejected with a helpful, actionable error.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

/**
 * Builds a human-readable message explaining that a given body type can't be
 * sent from the Swagger panel and pointing the user at the supported options.
 */
export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. ` +
  `The Swagger panel can only send text-based bodies (JSON, URL-encoded forms, plain text).`;

const createUnsupportedBodyError = (bodyType, detail) => {
  const error = new TypeError(`${detail} ${UNSUPPORTED_BODY_MESSAGE(bodyType)}`);
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

const isInstanceOf = (value, ctorName) => {
  const Ctor = typeof globalThis !== 'undefined' ? globalThis[ctorName] : undefined;
  return typeof Ctor === 'function' && value instanceof Ctor;
};

export const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (isInstanceOf(body, 'URLSearchParams')) {
    return body.toString();
  }

  if (isInstanceOf(body, 'FormData')) {
    throw createUnsupportedBodyError(
      'FormData',
      "Multipart form data can't be sent from the Swagger panel. Create a Bruno request to send multipart/form-data."
    );
  }

  // File extends Blob, so it must be checked first.
  if (isInstanceOf(body, 'File')) {
    throw createUnsupportedBodyError(
      'File',
      "File upload can't be sent from the Swagger panel. Create a Bruno request to upload a file."
    );
  }

  if (isInstanceOf(body, 'Blob')) {
    throw createUnsupportedBodyError(
      'Blob',
      "Binary file upload can't be sent from the Swagger panel. Create a Bruno request to send binary data."
    );
  }

  if (isInstanceOf(body, 'ArrayBuffer')) {
    throw createUnsupportedBodyError(
      'ArrayBuffer',
      "Binary data can't be sent from the Swagger panel. Create a Bruno request to send binary data."
    );
  }

  if (ArrayBuffer.isView(body)) {
    const bodyType = (body.constructor && body.constructor.name) || 'TypedArray';
    throw createUnsupportedBodyError(
      bodyType,
      "Binary data can't be sent from the Swagger panel. Create a Bruno request to send binary data."
    );
  }

  const bodyType = (body.constructor && body.constructor.name) || typeof body;
  throw createUnsupportedBodyError(
    bodyType,
    "This body type can't be sent from the Swagger panel."
  );
};

export default serializeBody;
